{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyMeoIl1V66VRjkbSI1QflUh"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"e30bb2cc","executionInfo":{"status":"ok","timestamp":1791746975659,"user_tz":300,"elapsed":14,"user":{"displayName":"Ali Jazib Rizvi","userId":"09227299734712609390"}},"outputId":"5de547b8-3c83-4313-9da3-829df8b5b01b"},"source":["%%writefile utils.py\n","import pandas as pd\n","import numpy as np\n","import ast\n","from sklearn.impute import KNNImputer, SimpleImputer\n","\n","def clean_and_impute_data(df: pd.DataFrame) -> pd.DataFrame:\n","    \"\"\"\n","    Cleans raw DataFrame, parses spatial coordinates from string/list columns,\n","    standardizes timestamps to match duration metrics, and handles missing values\n","    using KNN and Simple Imputers.\n","    \"\"\"\n","    df_clean = df.copy()\n","\n","    # 1. Parse string representations of lists/tuples safely\n","    def parse_location(loc_str):\n","        if isinstance(loc_str, str):\n","            try:\n","                return ast.literal_eval(loc_str)\n","            except (ValueError, SyntaxError):\n","                return np.nan\n","        return loc_str\n","\n","    for loc_col in ['location', 'pass_end_location', 'carry_end_location']:\n","        if loc_col in df_clean.columns:\n","            df_clean[loc_col] = df_clean[loc_col].apply(parse_location)\n","\n","    # 2. Timestamp Standardization\n","    def standardize_timestamp(ts):\n","        if pd.isna(ts):\n","            return np.nan\n","        try:\n","            td = pd.to_timedelta(ts)\n","            return round(td.total_seconds() / 60, 2)\n","        except ValueError:\n","            return np.nan\n","\n","    if 'timestamp' in df_clean.columns:\n","        df_clean['minutes_raw'] = df_clean['timestamp'].apply(standardize_timestamp)\n","        min_val = df_clean['minutes_raw'].min()\n","        max_val = df_clean['minutes_raw'].max()\n","        if max_val != min_val:\n","            df_clean['standardized_timestamp'] = (((df_clean['minutes_raw'] - min_val) / (max_val - min_val)) * 90).round(2)\n","        else:\n","            df_clean['standardized_timestamp'] = 0.0\n","        df_clean.drop(columns=['minutes_raw'], inplace=True)\n","\n","    # 3. Handle Missing Values via Imputation\n","    num_cols = df_clean.select_dtypes(include=['float', 'int64']).columns\n","    if len(num_cols) > 0:\n","        knn_imputer = KNNImputer(n_neighbors=5)\n","        df_clean[num_cols] = knn_imputer.fit_transform(df_clean[num_cols])\n","\n","    cat_cols = df_clean.select_dtypes(include=['object', 'bool']).columns\n","    if len(cat_cols) > 0:\n","        simple_imputer = SimpleImputer(strategy='most_frequent')\n","        df_clean[cat_cols] = simple_imputer.fit_transform(df_clean[cat_cols])\n","\n","    return df_clean\n","\n","\n","def process_and_compress_spatial_events(df: pd.DataFrame) -> pd.DataFrame:\n","    \"\"\"\n","    Filters for key on-ball movement events, extracts coordinate dimensions,\n","    computes movement vectors (deltas, distances), and flags progressive actions.\n","    \"\"\"\n","    # Filter and Copy\n","    events = df[df['type'].isin(['Pass', 'Carry', 'Dribble'])].copy()\n","\n","    # Extract start coordinates\n","    events['start_x'] = events['location'].apply(\n","        lambda loc: float(loc[0]) if isinstance(loc, (list, tuple)) and len(loc) >= 2 else np.nan\n","    )\n","    events['start_y'] = events['location'].apply(\n","        lambda loc: float(loc[1]) if isinstance(loc, (list, tuple)) and len(loc) >= 2 else np.nan\n","    )\n","\n","    # Extract end coordinates\n","    def get_end_x(row):\n","        if row['type'] == 'Pass' and isinstance(row.get('pass_end_location'), (list, tuple)):\n","            return float(row['pass_end_location'][0])\n","        elif row['type'] == 'Carry' and isinstance(row.get('carry_end_location'), (list, tuple)):\n","            return float(row['carry_end_location'][0])\n","        elif row['type'] == 'Dribble' and isinstance(row.get('location'), (list, tuple)):\n","            return float(row['location'][0]) + 3.0 if row.get('dribble_outcome') == 'Complete' else float(row['location'][0])\n","        return np.nan\n","\n","    def get_end_y(row):\n","        if row['type'] == 'Pass' and isinstance(row.get('pass_end_location'), (list, tuple)):\n","            return float(row['pass_end_location'][1])\n","        elif row['type'] == 'Carry' and isinstance(row.get('carry_end_location'), (list, tuple)):\n","            return float(row['carry_end_location'][1])\n","        elif row['type'] == 'Dribble' and isinstance(row.get('location'), (list, tuple)):\n","            return float(row['location'][1])\n","        return np.nan\n","\n","    events['end_x'] = events.apply(get_end_x, axis=1)\n","    events['end_y'] = events.apply(get_end_y, axis=1)\n","\n","    # Spatial calculations\n","    events['delta_x'] = events['end_x'] - events['start_x']\n","    events['delta_y'] = events['end_y'] - events['start_y']\n","    events['distance_yards'] = round(np.sqrt(events['delta_x']**2 + events['delta_y']**2), 2)\n","\n","    # Progressive Action Flags\n","    in_opp_box = (events['end_x'] >= 102.0) & (events['end_y'] >= 18.0) & (events['end_y'] <= 62.0)\n","\n","    events['is_progressive_pass'] = (\n","        (events['type'] == 'Pass') &\n","        (events.get('pass_outcome').isna()) &\n","        ((events['delta_x'] >= 10.0) | in_opp_box)\n","    )\n","    events['is_progressive_carry'] = (\n","        (events['type'] == 'Carry') &\n","        ((events['delta_x'] >= 10.0) | in_opp_box)\n","    )\n","    events['is_progressive_dribble'] = (\n","        (events['type'] == 'Dribble') &\n","        (events.get('dribble_outcome') == 'Complete') &\n","        (events['start_x'] >= 40.0)\n","    )\n","    events['is_progressive_action'] = (\n","        events['is_progressive_pass'] |\n","        events['is_progressive_carry'] |\n","        events['is_progressive_dribble']\n","    )\n","\n","    # Numeric mappings for aggregation\n","    for col in ['is_progressive_pass', 'is_progressive_carry', 'is_progressive_dribble', 'is_progressive_action']:\n","        events[col + '_num'] = events[col].astype(int)\n","\n","    # Outlier Removal on numeric columns\n","    for target in ['distance_yards']:\n","        if target in events.columns:\n","            events[target] = events[target].clip(\n","                lower=events[target].quantile(0.05),\n","                upper=events[target].quantile(0.95)\n","            )\n","\n","    core_columns = [\n","        'match_id', 'player', 'team', 'type', 'standardized_timestamp',\n","        'start_x', 'start_y', 'end_x', 'end_y',\n","        'delta_x', 'delta_y', 'distance_yards',\n","        'is_progressive_pass_num', 'is_progressive_carry_num',\n","        'is_progressive_dribble_num', 'is_progressive_action_num',\n","        'defensive_effort_count',\n","        'avg_pass_length', 'most_frequent_pass_style', 'total_ball_possession_events_per_match'\n","    ]\n","\n","    if 'num_events' not in events.columns:\n","        events['num_events'] = 1\n","    core_columns.append('num_events')\n","\n","    if 'mean_progressive_action_score' in events.columns:\n","        events['mean_progressive_action_score'] = events['mean_progressive_action_score'].clip(\n","            lower=events['mean_progressive_action_score'].quantile(0.05),\n","            upper=events['mean_progressive_action_score'].quantile(0.95)\n","        )\n","        core_columns.append('mean_progressive_action_score')\n","\n","    if 'league_name' in events.columns:\n","        core_columns.append('league_name')\n","\n","    return events[core_columns].copy()\n","\n","\n","def generate_player_metrics(spatial_df: pd.DataFrame) -> pd.DataFrame:\n","    \"\"\"\n","    Aggregates spatial and progressive action properties into player-level matrices\n","    and computes advanced ratios (e.g., verticality, pitch tilt share).\n","    \"\"\"\n","    agg_dict = {\n","        'total_events': ('num_events', 'count'),\n","        'total_distance_yards': ('distance_yards', 'sum'),\n","        'total_delta_x': ('delta_x', 'sum'),\n","        'mean_delta_x': ('delta_x', 'mean'),\n","        'total_delta_y': ('delta_y', 'sum'),\n","        'mean_delta_y': ('delta_y', 'mean'),\n","        'prog_passes': ('is_progressive_pass_num', 'sum'),\n","        'prog_carries': ('is_progressive_carry_num', 'sum'),\n","        'prog_dribbles': ('is_progressive_dribble_num', 'sum'),\n","        'total_prog_actions': ('is_progressive_action_num', 'sum'),\n","        'final_third_entries': ('end_x', lambda x: (x >= 80).sum())\n","    }\n","\n","    if 'mean_progressive_action_score' in spatial_df.columns:\n","        agg_dict['mean_progressive_action_score'] = ('mean_progressive_action_score', 'mean')\n","\n","    group_cols = ['player', 'team']\n","    if 'league_name' in spatial_df.columns:\n","        group_cols.append('league_name')\n","\n","    player_matrix = spatial_df.groupby(group_cols).agg(**agg_dict).reset_index()\n","\n","    # Ratios & Rate Feature Engineering\n","    player_matrix['prog_action_ratio'] = player_matrix['total_prog_actions'] / player_matrix['total_events']\n","    player_matrix['prog_pass_share'] = player_matrix['prog_passes'] / (player_matrix['total_prog_actions'] + 1e-5)\n","    player_matrix['verticality_index'] = player_matrix['total_delta_x'] / (player_matrix['total_distance_yards'] + 1e-5)\n","    player_matrix['pitch_tilt_ratio'] = player_matrix['final_third_entries'] / player_matrix['total_events']\n","\n","    return player_matrix"],"execution_count":1,"outputs":[{"output_type":"stream","name":"stdout","text":["Writing utils.py\n"]}]}]}